bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
tag=create-videobot:inplace-6f682c32
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || { echo VIDEO_POLL_STOPPED; exit 61; }
test "$(docker inspect "$cid" --format '{{.Config.Image}}')" = "$tag" || { echo VIDEO_WRONG_ACTIVE_IMAGE; exit 62; }
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect "$tag" --format '{{.Id}}')" || { echo VIDEO_IMAGE_ID_MISMATCH; exit 63; }
docker exec "$cid" sh -c 'test -f /opt/videobot/src/operations/replaceInvoiceAlbumWithRich.mjs && grep -Fq "VIDEO_INPLACE_TELEGRAM_ACK_UNKNOWN_KEEP_OLD_ALBUM" /opt/videobot/src/operations/replaceInvoiceAlbumWithRich.mjs && grep -Fq "vid:buy:" /opt/videobot/src/telegram/creatorBot.mjs' || { echo VIDEO_ACTIVE_CALLBACK_OR_EDIT_MISSING; exit 64; }
echo VIDEO_CURRENT_IMAGE_CALLBACK_AND_EDITOR=PASS
